#' Relative
#'
#' 
#' @param data .
#' @param X .
#' @param name .
#' @param base .
#' @param st .
#' @param rr1 .
#' @param rr2 .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$rr} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$rt} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$rt$asDF}
#'
#' \code{as.data.frame(results$rt)}
#'
#' @export
Relative <- function(
    data,
    X,
    name,
    base = "100",
    st = 0,
    rr1,
    rr2) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("Relative requires jmvcore to be installed (restart may be required)")

    if ( ! missing(X)) X <- jmvcore::resolveQuo(jmvcore::enquo(X))
    if ( ! missing(name)) name <- jmvcore::resolveQuo(jmvcore::enquo(name))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(X), X, NULL),
            `if`( ! missing(name), name, NULL))


    options <- RelativeOptions$new(
        X = X,
        name = name,
        base = base,
        st = st,
        rr1 = rr1,
        rr2 = rr2)

    analysis <- RelativeClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

